    ('5c4b5895-f5dd-4153-b6a5-8ebcfbbd9b68'::uuid, 'the-rise-of-intelligent-work-how-young-professionals-are-redefining-the-', 'the-rise-of-intelligent-work-how-young-professionals-are-redefining-the')
),
verified AS (
  SELECT c.article_id, c.old_slug, c.new_slug
  FROM cleanup c
  JOIN public.articles a ON a.id = c.article_id
  WHERE a.status = 'published'
    AND a.slug = c.old_slug
    AND c.new_slug ~ '^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$'
    AND c.new_slug NOT LIKE '%--%'
    AND right(c.new_slug, 1) <> '-'
    AND NOT EXISTS (
      SELECT 1 FROM public.articles other
      WHERE other.slug = c.new_slug AND other.id <> c.article_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.article_slug_redirects r
      WHERE r.old_slug = c.old_slug AND r.article_id <> c.article_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.article_slug_redirects r
      WHERE r.old_slug = c.new_slug AND r.article_id <> c.article_id
    )
),
guard AS (
  SELECT 1 / CASE
    WHEN (SELECT count(*) FROM cleanup) = 302
     AND (SELECT count(*) FROM verified) = 302
     AND (SELECT count(*) FROM public.articles WHERE status = 'published') = 1271
    THEN 1 ELSE 0
  END AS ok
),
drop_new_slug_redirects AS (
  DELETE FROM public.article_slug_redirects r
  USING verified v, guard g
  WHERE r.old_slug = v.new_slug
  RETURNING r.old_slug
),
ins AS (
  INSERT INTO public.article_slug_redirects (old_slug, article_id)
  SELECT v.old_slug, v.article_id
  FROM verified v, guard g
  WHERE NOT EXISTS (
    SELECT 1 FROM public.article_slug_redirects r WHERE r.old_slug = v.old_slug
  )
  RETURNING old_slug
),
upd AS (
  UPDATE public.articles a
  SET slug = v.new_slug
  FROM verified v, guard g
  WHERE a.id = v.article_id
    AND a.slug = v.old_slug
    AND a.status = 'published'
  RETURNING a.id
)
SELECT
  (SELECT count(*) FROM ins) AS redirects_created,
  (SELECT count(*) FROM upd) AS articles_updated;
